INSERT OR IGNORE INTO realtime_updates (id, title, headline, category, category_badge, summary, full_body, photo, author, date, display_date, timestamp, created_at)
VALUES 
('news-ramayana-2026', 'Ramayana Movie Release Announced', 'Grand Cinematic Adaptation of Ramayana Slated for Worldwide Theatrical Release', 'Real-Time News', '✦ Breaking Cinema', 'Director Nitesh Tiwari and the production studio have officially locked release dates for the much-anticipated epic cinematic adaptation.', 'The epic narrative featuring Ranbir Kapoor, Sai Pallavi, and Yash promises unprecedented visual craftsmanship and cultural fidelity across two consecutive chapters.', 'https://ik.imagekit.io/acooladescreenlady/screenlady/news/ramayana_MHoDF4dFm.jpeg', 'Screenlady News Desk', '2026-11-20', 'Nov 20, 2026', 1795100000000, '2026-11-20T10:00:00Z'),
('news-sindhutai-tribute', 'Remembering Sindhutai Sapkal (Mai)', 'A Soul of Infinite Compassion: Remembering Sindhutai Sapkal on Her Birth Anniversary', 'Real-Time News', '✦ National Tribute', 'Accolade Screenlady pays homage to the legendary mother of over a thousand orphans whose lifelong resilience inspired India.', 'Sindhutai Sapkal transformed personal adversity into a sanctuary of warmth and education for orphaned children across Maharashtra.', 'https://ik.imagekit.io/acooladescreenlady/screenlady/news/sindhutai-sapkal_dknv3p48S.jpeg', 'Editorial Board', '2026-11-14', 'Nov 14, 2026', 1795000000000, '2026-11-14T09:00:00Z'),
('news-box-office-nov', 'November Box Office Releases', 'Diwali & November Theatrical Releases Set Up Intense Multi-Starrer Box Office Showdowns', 'Real-Time News', '✦ Box Office Report', 'Singham Again and Bhool Bhulaiyaa 3 record tremendous opening footfalls across metropolitan and tier-2 cinema circuits.', 'Industry analysts report record-breaking advance reservations in single screens and multiplex chains alike.', 'https://ik.imagekit.io/acooladescreenlady/screenlady/news/films-box-office_75XoKxV1p.jpeg', 'Trade Analyst Team', '2026-11-08', 'Nov 08, 2026', 1794900000000, '2026-11-08T14:30:00Z'),
('news-amitabh-jalsa', 'Amitabh Bachchan Sunday Jalsa Meet', 'Iconic Sunday Fan Greetings at Jalsa Resume with Overwhelming Crowd Presence', 'Real-Time News', '✦ Star Dispatch', 'Megastar Amitabh Bachchan graciously stepped outside his residence Jalsa to greet thousands of ardent admirers waiting along the boulevard.', 'Dressed in customary white attire, the veteran thespian expressed heartfelt gratitude to fans who gathered from all corners of India.', 'https://ik.imagekit.io/acooladescreenlady/screenlady/news/amitabh-bachchan_u0N7Lg61t.jpeg', 'Screenlady Mumbai Bureau', '2026-11-03', 'Nov 03, 2026', 1794800000000, '2026-11-03T18:00:00Z');

