-- 8. Editorials (/editorials)
INSERT OR IGNORE INTO editorials (id, title, author, author_designation, read_time, pull_quote, summary, full_body, photo, category, category_badge, date, display_date, timestamp, created_at)
VALUES
('editorial-saree-canvas', 'Saree: A Canvas of Indian Womanhood', 'Mrs. Amruta Rao', 'Editor-in-Chief', '5 Min Read', 'The six yards of fabric are not mere attire; they are an unbroken thread of memory, resistance, and grace.', 'Exploring how the saree continues to weave personal stories, generational wisdom, and timeless identity across Indian society.', 'Across millennia, the saree has quietly witnessed and accompanied the evolution of Indian women. From the handloom cooperatives of Bengal and the shimmering zari borders of Kanchipuram to the executive boardrooms of modern Bengaluru and Mumbai, it has never been a static costume. Instead, it remains an intimate dialogue between craftsmanship and individuality.', 'https://ik.imagekit.io/acooladescreenlady/assets/images/featured-icon-saree.jpg', 'Editorial', 'Editorial Column', '2026-11-19', 'Nov 19, 2026', 1795096000000, '2026-11-19T09:00:00Z'),
('editorial-women-cinema', 'Behind the Lens: Women Shaping Classical Cinema', 'Mr. Prashant Chandrakant Sagvekar', 'Founder & Publisher', '6 Min Read', 'True cinema begins when the unseen emotional undercurrent is captured with fearless authenticity.', 'Reflecting on the pioneering women cinematographers, editors, and directors who reshaped classical cinematic grammar.', 'Behind the dazzling lights of film sets lies a craft of immense patience and visionary perception. When women take their place behind the viewfinder, the gaze shifts from spectacle to intimacy. This piece explores the transformative decades that established women as indispensable architects of cinematic storytelling.', 'https://ik.imagekit.io/acooladescreenlady/assets/images/articles/article-3.jpg', 'Cinema Commentary', 'Publisher Essay', '2026-11-11', 'Nov 11, 2026', 1794940000000, '2026-11-11T10:00:00Z');

